      "support": ["E14", "E15"],
      "counterevidence": ["E15"],
      "unknown": "Other pages were not inspected for additional comparison conditions or qualifications."
    },
    {
      "check_id": "C2",
      "status": "supported",
      "finding": "The Lite ablations test search, editing, file-viewer window size, and context handling. The results show performance differences among tested interface choices.",
      "support": ["E15", "E16"],
      "counterevidence": [],
      "unknown": "The inspected extracts do not establish robustness across repeated runs or benchmarks."
    },
    {
      "check_id": "C3",
